// Inyectar bloques de monetización adicionales según el nicho
const post = $input.item.json;
const niche = post.NICHO || 'general';
const lang = post.IDIOMA || 'es';
const es = lang === 'es';

// Bloques de monetización hardcodeados por nicho
// EDITAR ESTOS VALORES con tus links reales de Hotmart, Gumroad, WhatsApp
const MONETIZATION_BLOCKS = {
  default_es: {
    hotmart: `<div class="cta-hotmart" style="background:#fff3cd;border-left:4px solid #ffc107;padding:16px;margin:24px 0;border-radius:4px">
<strong>📚 Curso recomendado:</strong> Aprende más sobre este tema con nuestro curso completo.
<br><a href="<!-- HOTMART_URL -->" target="_blank" style="color:#e67e22;font-weight:bold">Ver curso en Hotmart →</a>
</div>`,
    whatsapp: `<div class="cta-whatsapp" style="background:#e8f5e9;border-left:4px solid #25D366;padding:16px;margin:24px 0;border-radius:4px">
<strong>💬 ¿Tienes preguntas?</strong> Escríbenos directamente por WhatsApp.
<br><a href="<!-- WHATSAPP_URL -->" target="_blank" style="color:#25D366;font-weight:bold">Contactar por WhatsApp →</a>
</div>`,
    newsletter: `<div class="cta-newsletter" style="background:#e3f2fd;border-left:4px solid #2196F3;padding:16px;margin:24px 0;border-radius:4px">
<strong>📧 Recibe artículos gratis:</strong> Suscríbete a nuestra newsletter y recibe contenido exclusivo.
<br><a href="<!-- NEWSLETTER_URL -->" target="_blank" style="color:#1976D2;font-weight:bold">Suscribirme gratis →</a>
</div>`
  },
  default_en: {
    hotmart: `<div class="cta-product" style="background:#fff3cd;border-left:4px solid #ffc107;padding:16px;margin:24px 0;border-radius:4px">
<strong>📚 Recommended course:</strong> Master this topic with our complete guide.
<br><a href="<!-- HOTMART_URL -->" target="_blank" style="color:#e67e22;font-weight:bold">View course →</a>
</div>`,
    whatsapp: `<div class="cta-whatsapp" style="background:#e8f5e9;border-left:4px solid #25D366;padding:16px;margin:24px 0;border-radius:4px">
<strong>💬 Need help?</strong> Contact us directly.
<br><a href="<!-- WHATSAPP_URL -->" target="_blank" style="color:#25D366;font-weight:bold">Contact us →</a>
</div>`,
    newsletter: `<div class="cta-newsletter" style="background:#e3f2fd;border-left:4px solid #2196F3;padding:16px;margin:24px 0;border-radius:4px">
<strong>📧 Get free articles:</strong> Subscribe to our newsletter.
<br><a href="<!-- NEWSLETTER_URL -->" target="_blank" style="color:#1976D2;font-weight:bold">Subscribe free →</a>
</div>`
  }
};

const blocks = es ? MONETIZATION_BLOCKS.default_es : MONETIZATION_BLOCKS.default_en;

// El HTML del post ya tiene los bloques base de Telegram y productos de Amazon
// Este workflow añade Hotmart + WhatsApp + Newsletter al final del post
const additionalBlocks = `
${blocks.hotmart}
${blocks.whatsapp}
${blocks.newsletter}`;

return {
  json: {
    ID_UNICO: post.ID_UNICO,
    POST_ID: post.POST_ID,
    BLOG_ID: post.ID_BLOG,
    PUBLISHED_URL: post.URL_FINAL,
    ADDITIONAL_BLOCKS: additionalBlocks,
    TITLE: post.TITLE
  }
};

const postData = $input.item.json;
const prevData = $('Construir Bloques de Monetización').item.json;

// Añadir los bloques adicionales al final del contenido existente
const currentContent = postData.content || '';
const updatedContent = currentContent + prevData.ADDITIONAL_BLOCKS;

return {
  json: {
    ID_UNICO: prevData.ID_UNICO,
    POST_ID: prevData.POST_ID,
    BLOG_ID: prevData.ID_BLOG,
    UPDATED_CONTENT: updatedContent
  }
};
